window.RTLBenchLSData.register("assets/d3f76fe23d768d8b22cd9ef9c9d48f1eb80e5a63289f9fcd0c1e2415e536a604.txt","module origen_022756 (\n    input wire sys_rstn,\n    input wire clk_ref,\n    input wire ads_sdo0,\n    input wire ads_sdo1,\n    input wire ads_rvs,\n    output reg ads_csn,\n    output reg ads_rstn,\n    output reg ads_sclk,\n    output reg ads_sdi,\n    output reg dvalid,\n    output reg [15:0] dout\n);\n\n    // Parameters\n    localparam IDLE = 2'b00;\n    localparam DELAY = 2'b01;\n    localparam WRITE = 2'b10;\n\n    // Configuration registers\n    reg [31:0] cfg_reg0c_w = 32'h0C00_0000;\n    reg [31:0] cfg_reg10_w = 32'h1000_0000;\n    reg [31:0] cfg_reg14_w = 32'h1400_0000;\n    reg [31:0] cfg_reg10_r = 32'h9000_0000;\n\n    // Internal registers\n    reg [1:0] state;\n    reg [7:0] cfg_cnt;\n    reg [7:0] clk_cnt;\n    reg [31:0] shift_reg;\n    reg [31:0] cfg_word;\n\n    // State machine\n    always @(posedge clk_ref or negedge sys_rstn) begin\n        if (!sys_rstn) begin\n            state <= IDLE;\n            cfg_cnt <= 8'd0;\n            clk_cnt <= 8'd0;\n            ads_csn <= 1'b1;\n            ads_rstn <= 1'b0;\n            ads_sclk <= 1'b0;\n            ads_sdi <= 1'b0;\n            dvalid <= 1'b0;\n            dout <= 16'd0;\n        end else begin\n            case (state)\n                IDLE: begin\n                    ads_rstn <= 1'b1;\n                    if (clk_cnt == 8'd255) begin\n                        state <= DELAY;\n                        clk_cnt <= 8'd0;\n                    end else begin\n                        clk_cnt <= clk_cnt + 1'b1;\n                    end\n                end\n\n                DELAY: begin\n                    if (clk_cnt == 8'd255) begin\n                        state <= WRITE;\n                        clk_cnt <= 8'd0;\n                        ads_csn <= 1'b0;\n                        cfg_word <= cfg_reg0c_w;\n                    end else begin\n                        clk_cnt <= clk_cnt + 1'b1;\n                    end\n                end\n\n                WRITE: begin\n                    if (clk_cnt < 8'd32) begin\n                        if (clk_cnt[0] == 1'b0) begin\n                            ads_sclk <= 1'b1;\n                            ads_sdi <= cfg_word[31];\n                            cfg_word <= {cfg_word[30:0], 1'b0};\n                        end else begin\n                            ads_sclk <= 1'b0;\n                            shift_reg <= {shift_reg[30:0], ads_sdo0};\n                        end\n                        clk_cnt <= clk_cnt + 1'b1;\n                    end else begin\n                        ads_csn <= 1'b1;\n                        if (clk_cnt == 8'd255) begin\n                            clk_cnt <= 8'd0;\n                            if (cfg_cnt < 8'd3) begin\n                                cfg_cnt <= cfg_cnt + 1'b1;\n                                ads_csn <= 1'b0;\n                                case (cfg_cnt)\n                                    8'd0: cfg_word <= cfg_reg10_w;\n                                    8'd1: cfg_word <= cfg_reg14_w;\n                                    8'd2: cfg_word <= cfg_reg10_r;\n                                endcase\n                            end else begin\n                                dout <= shift_reg[31:16];\n                                dvalid <= 1'b1;\n                            end\n                        end else begin\n                            clk_cnt <= clk_cnt + 1'b1;\n                        end\n                    end\n                end\n\n                default: state <= IDLE;\n            endcase\n        end\n    end\n\nendmodule");
